@startuml

class Sober {
}

class Car {
    +licensePlate : string
}

class CarOwner {
    +name : string
}

class Accident {
    +date : date
    +location : string
    +damageAmount : double
}

abstract class TaxiService {
    +pickupTime : datetime
    +dropoffTime : datetime
    +pickupLocation : string
    +dropoffLocation : string
    +rideDuration : string
    +distance : double
}

class RideHailing extends TaxiService {
    +requestType : string
    +fee : double
    +numberOfPassengers : int
}

class RideSharing extends TaxiService {
    +upfrontNegotiatedFee : double
    +numberOfPassengers : int
}

class Customer {
    +name : string
}

class Passenger {
    +name : string
}

class RideHailingRequest {
    +estimatedWaitTime : string
}

class RideSharingBooking {
    +treesPlanted : int
}

Sober "1" -- "*" Car : operates
Sober "1" -- "*" CarOwner : tracks
Car "1" -- "*" Accident : involved in

Car "1" -- "0..1" CarOwner : owned by

TaxiService "1" -- "1" Car : provided by

RideHailing "1" -- "1" Customer : lead customer
RideHailing "1" -- "1..6" Passenger : carries

RideSharing "1" -- "1..10" Passenger : carries

RideHailing "1" -- "1" RideHailingRequest : generates

@enduml

